def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Strip build metadata
        version_core = v.split('+')[0]

        # Separate core and pre-release
        parts = version_core.split('-', 1)
        core_str = parts[0]
        pre_release_str = parts[1] if len(parts) > 1 else None

        # Parse core version
        core = [int(x) for x in core_str.split('.')]

        # Parse pre-release identifiers
        pre_release = []
        if pre_release_str:
            for part in pre_release_str.split('.'):
                if part.isdigit():
                    pre_release.append(int(part))
                else:
                    pre_release.append(part)

        return core, pre_release

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # 1. Compare core version (Major, Minor, Patch)
    if core_a > core_b:
        return 1
    if core_a < core_b:
        return -1

    # 2. Handle pre-release vs release
    # A version with a pre-release is lower than a version without one
    if pre_a and not pre_b:
        return -1
    if not pre_a and pre_b:
        return 1
    if not pre_a and not pre_b:
        return 0

    # 3. Compare pre-release identifiers
    for part_a, part_b in zip(pre_a, pre_b):
        if part_a == part_b:
            continue

        # Numeric identifiers are compared numerically, alphanumeric lexically
        # Numeric identifiers are always lower than non-numeric identifiers
        type_a = 'int' if isinstance(part_a, int) else 'str'
        type_b = 'int' if isinstance(part_b, int) else 'str'

        if type_a == type_b:
            if part_a < part_b:
                return -1
            else:
                return 1
        else:
            # One is int, one is str. Numeric < Alphanumeric.
            return -1 if type_a == 'int' else 1

    # 4. If all shared identifiers are equal, the shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
