import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # 1. Identify all unique nodes
    nodes = set(deps.keys())
    for neighbors in deps.values():
        nodes.update(neighbors)

    # 2. Build adjacency list (dependency -> item) and in-degree map
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # 3. Use a min-heap to handle alphabetical order for nodes with 0 in-degree
    ready_queue = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(ready_queue)

    order = []

    # 4. Kahn's algorithm
    while ready_queue:
        u = heapq.heappop(ready_queue)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready_queue, v)

    # 5. Check for cycles
    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependencies")

    return order
