def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    processed_words = []
    for word in words:
        if len(word) <= width:
            processed_words.append(word)
        else:
            for i in range(0, len(word), width):
                processed_words.append(word[i : i + width])

    lines = []
    if not processed_words:
        return []

    current_line = []
    current_length = -1  # Account for the space that would be added before the first word

    for word in processed_words:
        # If current_length + 1 (for space) + length of word > width
        # Note: current_length starts at -1, so the first word makes it 0
        if current_length + 1 + len(word) > width and current_line:
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)
        else:
            current_line.append(word)
            current_length += 1 + len(word)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
