import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    pattern = r'^((?P<h>\d+)h)?((?P<m>\d+)m)?((?P<s>\d+)s)?$'
    match = re.match(pattern, s)

    if not match or match.group(0) != s:
        raise ValueError(f"Invalid duration string: {s}")

    # Check if at least one group matched to avoid returning 0 for invalid empty-like matches
    if not any(match.group(g) for g in ['h', 'm', 's']):
        raise ValueError(f"Invalid duration string: {s}")

    seconds = 0
    if match.group('h'):
        seconds += int(match.group('h')) * 3600
    if match.group('m'):
        seconds += int(match.group('m')) * 60
    if match.group('s'):
        seconds += int(match.group('s'))

    return seconds
