    def parse_version(version_str: str):
        # Ignore build metadata
        version_str = version_str.split('+')[0]

        # Separate core version from pre-release
        if '-' in version_str:
            core_str, prerelease_str = version_str.split('-', 1)
            prerelease = prerelease_str.split('.')
        else:
            core_str = version_str
            prerelease = None

        # Parse core (major, minor, patch) as integers
        core = [int(x) for x in core_str.split('.')]
        return core, prerelease

    def compare_identifiers(id_a, id_b) -> int:
        # Check if identifiers are numeric
        is_a_digit = id_a.isdigit()
        is_b_digit = id_b.isdigit()

        if is_a_digit and is_b_digit:
            val_a, val_b = int(id_a), int(id_b)
            return (val_a > val_b) - (val_a < val_b)
        elif is_a_digit or is_b_digit:
            # Numeric identifiers have lower precedence than non-numeric
            return -1 if is_a_digit else 1
        else:
            # Both alphanumeric
            return (id_a > id_b) - (id_a < id_b)

    core_a, pre_a = parse_version(a)
    core_b, pre_b = parse_version(b)

    # 1. Compare core version (Major, Minor, Patch)
    for ca, cb in zip(core_a, core_b):
        if ca > cb: return 1
        if ca < cb: return -1

    # 2. Check release vs pre-release
    # A version with a pre-release is "lower" than a release version
    if pre_a is None and pre_b is not None:
        return 1
    if pre_a is not None and pre_b is None:
        return -1
    if pre_a is None and pre_b is None:
        return 0

    # 3. Compare pre-release identifiers
    for id_a, id_b in zip(pre_a, pre_b):
        res = compare_identifiers(id_a, id_b)
        if res != 0:
            return res

    # 4. If all common identifiers match, the shorter list is lower
    if len(pre_a) > len(pre_b):
        return 1
    if len(pre_a) < len(pre_b):
        return -1

    return 0
