def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    # Pre-process words to handle words longer than width
    processed_words = []
    for word in words:
        if len(word) <= width:
            processed_words.append(word)
        else:
            for i in range(0, len(word), width):
                processed_words.append(word[i : i + width])

    lines = []
    current_line_words = []
    current_line_len = 0

    for word in processed_words:
        word_len = len(word)

        # Check if adding this word (plus a space if not the first word) exceeds width
        space_needed = 1 if current_line_words else 0

        if current_line_len + space_needed + word_len <= width:
            current_line_words.append(word)
            current_line_len += space_needed + word_len
        else:
            # Finalize the current line and start a new one
            lines.append(" ".join(current_line_words))
            current_line_words = [word]
            current_line_len = word_len

